<template>
<section class="source-news-card" :class="{'source-news-dark':dark,'source-image-card':imageEnabled,'douban-movie-card':['douban','maoyan'].includes(sourceId),'video-hot-card':sourceId==='video_hot','cover-wide':sourceId==='video_hot'&&activeTab==='tx_video'}" :aria-labelledby="`source-title-${sourceId}`">
 <header class="source-heading"><div><h2 :id="`source-title-${sourceId}`"><img v-if="sourceIcon && !iconFailed" :src="sourceIcon" :class="{ 'cncert-wordmark': sourceId === 'cncert' }" alt="" width="24" height="24" referrerpolicy="no-referrer" @error="iconFailed=true" /><span class="source-title-text">{{config.name}}</span></h2></div><div class="source-heading-meta"><span role="status">{{status}}</span><a :href="config.url" target="_blank" rel="noopener noreferrer" title="访问原站" aria-label="访问原站">原站↗</a></div></header>
 <nav v-if="tabs.length" class="source-tabs" :aria-label="`${config.name}内容分类`"><button v-for="tab in tabs" :key="tab.id" type="button" :aria-pressed="activeTab===tab.id" @click="selectTab(tab.id)"><img v-if="tabIcon(tab.id)" class="source-tab-brand-icon" :src="tabIcon(tab.id)" alt="" width="16" height="16" />{{tab.label}}</button></nav>
 <div v-if="digest" class="source-digest"><div class="source-digest-top"><span class="source-digest-badge">AI 速览</span><span v-if="digest.basedOn" class="source-digest-meta">基于 {{digest.basedOn}} 条资讯</span></div><p class="source-digest-text">{{digest.text}}</p></div>
 <ol v-if="visible.length" class="source-list"><li v-for="(item,index) in visible" :key="item.url"><a :href="item.url" target="_blank" rel="noopener noreferrer"><div v-if="imageEnabled&&item.cover&&!failedCovers[item.url]" class="source-cover"><img :src="coverSrc(item.cover)" alt="" loading="lazy" referrerpolicy="no-referrer" @error="failedCovers[item.url]=true" /></div><div class="source-entry"><span class="source-rank" :class="{top:index<3,'model-rank':activeTab==='aa_models','geek-rank':['threat_research','nvd','pojie52'].includes(sourceId)}"><img v-if="activeTab==='aa_models' && tabIcon('aa_models')" :src="tabIcon('aa_models')" :class="['model-trophy-gold','model-trophy-yellow','model-trophy-copper'][index] || 'model-trophy-neutral'" alt="" width="16" height="16" />{{index+1}}</span><div class="source-copy"><h3 :class="{'news-recent':isRecent(item)}" :title="item.originalTitle || item.title">{{item.title}}</h3><p v-if="item.meta" :title="item.meta"><template v-if="activeTab==='aa_models'"><strong class="model-index">{{item.meta.split(' · ')[0]}}</strong>{{item.meta.slice(item.meta.split(' · ')[0].length)}}</template><template v-else>{{item.meta}}</template></p><div v-if="sourceId==='maoyan'||(sourceId==='douban'&&activeTab==='maoyan')" class="maoyan-metrics"><span>累计票房：{{item.boxOffice || "暂无数据"}}</span><span>猫眼评分：{{item.rating ? item.rating + " 分" : "暂无评分"}}</span></div></div></div></a></li></ol>
 <div v-else class="source-empty">{{loading?'正在加载…':'此来源当前未获取到内容，可通过上方入口访问原站。'}}<button v-if="!loading" type="button" @click="load(true)">重试</button></div>
 <footer><span>每小时获取</span><div class="source-footer-actions"><button v-if="tabs.length>1" type="button" class="source-switch" :title="`切换到${nextTabLabel}`" @click="cycleTab">切换：{{nextTabLabel}} →</button><button v-if="items.length>((sourceId==='short_video')?8:(sourceId==='pojie52'&&activeTab!=='kanxue')?10:6)" type="button" data-source-more :aria-expanded="showAll" @click="showAll=!showAll">{{showAll?'精简列表 ↑':'查看更多 ↓'}}</button></div></footer>
</section>
